// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.stream.Stream;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.sail.NotifyingSailConnection;
import org.eclipse.rdf4j.sail.lmdb.config.FrontierEstimatorMode;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.eclipse.rdf4j.sail.lmdb.frontier.FrontierStatisticsManifest;
import org.eclipse.rdf4j.sail.lmdb.frontier.FrontierStatisticsStatus;
import org.eclipse.rdf4j.sail.lmdb.frontier.LmdbStatisticsService;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * Every signed-delta publication writes a new manifest plus several shard files. Superseded generations must be retired
 * from disk instead of accumulating for the lifetime of the store.
 */
class LmdbFrontierGenerationRetirementTest {

	private static final String PREFIX = "urn:retirement:";

	@Test
	void supersededManifestsAreRetiredAfterEveryDeltaPublication(@TempDir Path dataDirectory) throws Exception {
		LmdbStore store = new LmdbStore(dataDirectory.toFile(), new LmdbStoreConfig("spoc,posc")
				.setFrontierEstimatorMode(FrontierEstimatorMode.AUTHORITATIVE)
				.setFrontierSynopsisBudgetBytes(32L * 1024L * 1024L));
		try {
			store.init();
			LmdbSailStore backing = store.getBackingStore();
			assertTrue(backing.awaitFrontierStatisticsReady(20_000L));
			ValueFactory vf = store.getValueFactory();
			IRI predicate = vf.createIRI(PREFIX + "m");
			for (int commit = 0; commit < 12; commit++) {
				try (NotifyingSailConnection connection = store.getConnection()) {
					connection.begin();
					connection.addStatement(vf.createIRI(PREFIX + "ms" + commit), predicate,
							vf.createLiteral(commit));
					connection.commit();
				}
				assertTrue(backing.awaitFrontierStatisticsCoveredSequence(latestSequence(backing), 15_000L));
			}
			Path frontierDirectory = dataDirectory.resolve("frontier-statistics-v2");
			List<String> manifests = names(frontierDirectory, "manifest-");
			List<String> shards = names(frontierDirectory, "generation-");
			long bytes = bytes(frontierDirectory);
			FrontierStatisticsStatus status = backing.frontierStatisticsStatus();
			long liveBytes = status.diskBytesByTier().values().stream().mapToLong(Long::longValue).sum();
			LmdbStatisticsService service = (LmdbStatisticsService) field(backing, "statisticsService");
			FrontierStatisticsManifest current = service.currentManifest().orElseThrow();
			String description = "after 12 single-statement commits: manifests=" + manifests + " shardFiles="
					+ shards.size() + " directoryBytes=" + bytes + " liveGenerationBytes=" + liveBytes;
			assertTrue(manifests.size() <= 3, "superseded Frontier manifests must be retired; " + description);
			assertTrue(manifests.contains("manifest-%019d.fs2m".formatted(current.generationId()))
					&& manifests.contains("manifest-%019d.fs2m".formatted(current.previousGenerationId())),
					"the current generation and its predecessor must be retained; " + description);
			for (String shard : shards) {
				assertTrue(generationOf(shard) <= current.generationId(),
						"no build was in progress, so no shard may be newer than the current generation; "
								+ description);
			}
			assertTrue(bytes < 2L * liveBytes, "the directory must hold at most the current generation plus the "
					+ "layers its predecessor still references (delta layers are shared across generations); "
					+ description);
		} finally {
			store.shutDown();
		}
	}

	private static long generationOf(String shardFileName) {
		String digits = shardFileName.substring("generation-".length(), shardFileName.indexOf("-shard-"));
		return Long.parseLong(digits);
	}

	private static List<String> names(Path directory, String prefix) throws IOException {
		try (Stream<Path> files = Files.list(directory)) {
			return files.map(path -> path.getFileName().toString())
					.filter(name -> name.startsWith(prefix))
					.sorted()
					.toList();
		}
	}

	private static long bytes(Path directory) throws IOException {
		try (Stream<Path> files = Files.list(directory)) {
			return files.filter(Files::isRegularFile).mapToLong(path -> {
				try {
					return Files.size(path);
				} catch (IOException e) {
					return 0L;
				}
			}).sum();
		}
	}

	private static Object field(LmdbSailStore backing, String name) throws Exception {
		Field field = LmdbSailStore.class.getDeclaredField(name);
		field.setAccessible(true);
		return field.get(backing);
	}

	private static long latestSequence(LmdbSailStore backing) throws Exception {
		Method method = LmdbSailStore.class.getDeclaredMethod("statementMutationStamp");
		method.setAccessible(true);
		return (long) method.invoke(backing);
	}
}
